using ShapeInventory.Core;

namespace ShapeInventory.Editor
{
    // Plain data holders for SampleContentData.cs (generated by Tools/verify_levels.py).

    internal sealed class ItemDef
    {
        public readonly string Id;
        public readonly string Name;
        public readonly string Hex;
        public readonly string[] Rows;

        public ItemDef(string id, string name, string hex, string[] rows)
        {
            Id = id;
            Name = name;
            Hex = hex;
            Rows = rows;
        }
    }

    /// <summary>An enchanted copy of a plain item shape: asset Item_&lt;type&gt;_&lt;baseId&gt;.</summary>
    internal sealed class EnchantedItemDef
    {
        public readonly EnchantmentType Type;
        public readonly string BaseId;

        public EnchantedItemDef(EnchantmentType type, string baseId)
        {
            Type = type;
            BaseId = baseId;
        }

        /// <summary>"sharpness_i4"</summary>
        public string Id
        {
            get { return Type.ToString().ToLowerInvariant() + "_" + BaseId; }
        }
    }

    internal sealed class ObjectDef
    {
        public readonly string Id;
        public readonly string Name;
        public readonly string Hex;
        public readonly string[] Rows;

        public ObjectDef(string id, string name, string hex, string[] rows)
        {
            Id = id;
            Name = name;
            Hex = hex;
            Rows = rows;
        }
    }

    internal sealed class LevelDef
    {
        public readonly string AssetName;
        public readonly string ObjectId;
        public readonly string Story;
        public readonly EnchantmentRequirement[] Requirements;
        public readonly string[] ItemIds;
        public readonly string SuccessText;
        public readonly string PartialText;
        public readonly string FailureText;

        public LevelDef(string assetName, string objectId, string story, EnchantmentRequirement[] requirements,
            string[] itemIds, string successText, string partialText, string failureText)
        {
            AssetName = assetName;
            ObjectId = objectId;
            Story = story;
            Requirements = requirements;
            ItemIds = itemIds;
            SuccessText = successText;
            PartialText = partialText;
            FailureText = failureText;
        }
    }
}
